
(()=>{const themes={purple:['#09070d','#14101c','#a855f7','#c084fc','#6d28d9','#2c2239','#634182'],blue:['#070b12','#101b2b','#438af7','#91c1ff','#2456ad','#23374c','#476b95'],green:['#070e0b','#102019','#39a878','#83dfb2','#216f50','#254435','#41765c'],red:['#110809','#231215','#e15b70','#ff9cac','#a43046','#492930','#8c4a58'],orange:['#100b07','#24190f','#db873a','#ffc18a','#945414','#493525','#8b6444'],pink:['#100811','#231125','#d569c8','#f6a6e9','#963889','#452747','#825185'],gray:['#090b0e','#171b22','#a1adbd','#e0e5ed','#566273','#303844','#647083']};Object.assign(themes,{christmas:['#07100d','#10251b','#da5265','#9be7bb','#ad253c','#294b37','#ad6c49'],halloween:['#0d0906','#21160e','#ff872f','#ffc17a','#ac4714','#4b3020','#a05a30'],patrick:['#061109','#102619','#48c578','#b3ed9e','#207347','#2b4f36','#658346'],canada:['#10090b','#241316','#ee5968','#fff0f1','#b1273b','#50272e','#a05460'],newyear:['#0d0b13','#211b2c','#d9b65e','#ffe8a3','#876b23','#473b55','#9c8050']});const keys=['--bg','--panel','--purple','--purple-hi','--violet','--line','--line-hi'];function apply(name){if(!Object.hasOwn(themes,name))name='purple';keys.forEach((key,i)=>document.documentElement.style.setProperty(key,themes[name][i]));document.documentElement.dataset.theme=name;return name}let saved='purple';try{saved=localStorage.getItem('purple-dragon-theme')||saved}catch{}apply(saved);document.addEventListener('DOMContentLoaded',()=>{const select=document.getElementById('theme-select');select.value=document.documentElement.dataset.theme;select.addEventListener('change',()=>{const name=apply(select.value);try{localStorage.setItem('purple-dragon-theme',name)}catch{}document.dispatchEvent(new Event('purple-theme-change'))})})})();
